/**
 * The module mirror: the app serves the renderers' module CDNs from its own
 * origin at `<api>/mirror/<host>/…` (api/routes/mirror.py). The document
 * import maps in index.html and public/sandbox.html route ES module imports
 * there; `mirrorUrl` maps the loads an import map does not cover (a
 * stylesheet `<link>`, a fetched module body).
 */
// GENERATED by sdk/scripts/sync_mirror_hosts.py from sdk/src/collimate/module_mirror_contract.json `upstreams`; do not edit.
export const MIRRORED_HOSTS: ReadonlySet<string> = new Set(['esm.sh', 'cdn.jsdelivr.net']);
// END GENERATED

/** `url` on the mirror under `apiBase` (as `getApiUrl()` gives it), or unchanged when it is not on a mirrored CDN. */
export function mirrorUrl(url: string, apiBase: string): string {
  let parsed: URL;
  try { parsed = new URL(url); } catch { return url; }
  if (parsed.protocol !== 'https:' || !MIRRORED_HOSTS.has(parsed.host) || parsed.username || parsed.password) return url;
  return `${apiBase.replace(/\/+$/, '')}/mirror/${parsed.host}${parsed.pathname}${parsed.search}`;
}
